input.command:
# List ALL node processes with full command lines
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | ForEach-Object {
  $cl = $_.CommandLine
  if ($cl -match 'rootmc-ava|index\.mjs|server\.mjs|poller\.mjs') {
    Write-Host "PID=$($_.ProcessId) CL=$cl"
  }
}
Write-Host "==== kill matching ===="
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'rootmc-ava|[/\\]src[/\\](index|server|poller)\.mjs'
} | ForEach-Object {
  Write-Host "Killing $($_.ProcessId)"
  Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}
Start-Sleep -Seconds 3
Write-Host "==== remaining ===="
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'rootmc-ava|[/\\]src[/\\](index|server|poller)\.mjs|\ssrc/(index|server|poller)\.mjs'
} | ForEach-Object { "STILL PID=$($_.ProcessId) $($_.CommandLine)" }
# Also kill plain "src/index.mjs" without path
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'src[/\\](index|server|poller)\.mjs'
} | ForEach-Object {
  Write-Host "Killing relative $($_.ProcessId): $($_.CommandLine)"
  Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}
Start-Sleep -Seconds 2
# Start with absolute path so CommandLine matches
$env:AVA_NO_STATUS_WINDOW='1'
$ava = 'D:\.1 Work Stations\RootMC\Web Files\rootmc-ava'
$p = Start-Process -FilePath 'C:\Program Files\nodejs\node.exe' -ArgumentList "`"$ava\src\index.mjs`"" -WorkingDirectory $ava -WindowStyle Hidden -PassThru
Write-Host "Started PID=$($p.Id) HasExited=$($p.HasExited)"
Start-Sleep -Seconds 12
Write-Host "==== after start ===="
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'rootmc-ava|src[/\\](index|server|poller)\.mjs'
} | ForEach-Object { "$($_.ProcessId) $($_.CommandLine)" }
try {
  $h = Invoke-RestMethod -Uri 'http://127.0.0.1:8787/health'
  $h | ConvertTo-Json -Depth 8
  # if poller dead, wait more
  if (-not $h.asleep -or -not $h.children.'poller.mjs'.alive) {
    Write-Host "Waiting more for poller/heartbeat..."
    Start-Sleep -Seconds 10
    Invoke-RestMethod -Uri 'http://127.0.0.1:8787/health' | ConvertTo-Json -Depth 8
  }
} catch { Write-Host "health err: $_" }
Get-Content "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data\heartbeat.json" -ErrorAction SilentlyContinue

# Kill all Ava node processes (index/server/poller absolute or relative)
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'rootmc-ava|src[/\\](index|server|poller)\.mjs'
} | ForEach-Object {
  Write-Host "Kill $($_.ProcessId)"
  Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}
Start-Sleep -Seconds 3
$env:AVA_NO_STATUS_WINDOW='1'
$ava = 'D:\.1 Work Stations\RootMC\Web Files\rootmc-ava'
$p = Start-Process -FilePath 'C:\Program Files\nodejs\node.exe' -ArgumentList "`"$ava\src\index.mjs`"" -WorkingDirectory $ava -WindowStyle Hidden -PassThru
Write-Host "Started $($p.Id)"
Start-Sleep -Seconds 10
Get-CimInstance Win32_Process -Filter "Name = 'node.exe'" | Where-Object {
  $_.CommandLine -match 'rootmc-ava|src[/\\](index|server|poller)\.mjs'
} | ForEach-Object { "$($_.ProcessId) $($_.CommandLine)" }
Write-Host "==== HEALTH ===="
$h = Invoke-RestMethod -Uri 'http://127.0.0.1:8787/health'
$h | ConvertTo-Json -Depth 8
if (-not $h.asleep) {
  Start-Sleep -Seconds 8
  Write-Host "==== HEALTH RETRY ===="
  Invoke-RestMethod -Uri 'http://127.0.0.1:8787/health' | ConvertTo-Json -Depth 8
}
Get-Content "D:\.1 Work Stations\RootMC\Server Handoffs\Ava Ivy\data\heartbeat.json"

cd "D:\.1 Work Stations\RootMC\Web Files\rootmc-ava"
node --input-type=module -e @"
import { loadEnv, botToken } from './src/config.mjs';
import { makeFetchJson, postMessage } from './src/discordApi.mjs';
import { loadSleepState, discordStamp } from './src/sleepMode.mjs';
import { storePaths } from './src/store.mjs';

await loadEnv();
storePaths();
const env = await loadEnv();
const fetchJson = makeFetchJson(botToken(env));
const sleep = loadSleepState();
const wakeStamp = discordStamp(sleep?.wakeAt);
const content = [
  'heading to sleep — dreaming until about **10:00 HST** (' + wakeStamp + ').',
  '',
  'summons still get a sleepy reply; i will read the chat when i wake.',
  'goodnight.',
].join('\n');
const msg = await postMessage(fetchJson, '1516108586307158088', content);
console.log(JSON.stringify({ id: msg.id, channel_id: msg.channel_id, content: msg.content }, null, 2));
"@
